<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { accessSession } from '../stores/access'
import { dataCatalogApi, type Availability, type CatalogPair, type CatalogResponse } from '../api/dataCatalog'
import TablePager from '../components/TablePager.vue'
import UiIcon from '../components/UiIcon.vue'
import MethodsPageHeader from '../components/MethodsPageHeader.vue'
import { downloadBlob } from '../utils/csv'

const route = useRoute()
const allContexts = ['HepG2', 'Jurkat', 'K562', 'RPE1']
const readOnly = computed(() => Boolean(accessSession.value?.read_only))
const contexts = computed(() => readOnly.value ? data.value?.summary.contexts.map(row => row.cell_line) ?? [] : allContexts)
const cellLine = ref(allContexts.includes(String(route.query.cell_line)) ? String(route.query.cell_line) : '')
const term = ref(typeof route.query.perturbation === 'string' ? route.query.perturbation : '')
const availability = ref<Availability>('all'), support = ref('all')
const page = ref(1), pageSize = ref(20)
const data = ref<CatalogResponse | null>(null), loading = ref(false), error = ref('')
const downloading = ref(false), downloadError = ref('')
let controller: AbortController | undefined, downloadController: AbortController | undefined
let timer: ReturnType<typeof setTimeout> | undefined
const pages = computed(() => Math.max(1, Math.ceil((data.value?.total ?? 0) / pageSize.value)))
function filters() {
  return { cell_line: cellLine.value || undefined, query: term.value.trim(), availability: availability.value,
    model_supported: support.value === 'all' ? undefined : support.value === 'yes' }
}
async function load() {
  controller?.abort()
  const current = controller = new AbortController()
  loading.value = true; error.value = ''
  try {
    const result = await dataCatalogApi.query({ ...filters(), limit: pageSize.value,
      offset: (page.value - 1) * pageSize.value }, current.signal)
    if (!current.signal.aborted) data.value = result
  } catch (reason) {
    if (!current.signal.aborted) error.value = reason instanceof Error ? reason.message : '数据目录读取失败'
  } finally { if (!current.signal.aborted) loading.value = false }
}
watch([cellLine, term, availability, support], () => {
  page.value = 1; controller?.abort(); clearTimeout(timer)
  timer = setTimeout(() => { void load() }, 200)
})
watch([page, pageSize], () => { clearTimeout(timer); void load() })
void load()
onBeforeUnmount(() => { clearTimeout(timer); controller?.abort(); downloadController?.abort() })
function destination(row: CatalogPair, path: string) {
  return { path: '/research', query: { type: path === '/measured' ? 'measured' : 'prediction', cell_line: row.cell_line, perturbation: row.perturbation } }
}
function chooseContext(value: string) {
  cellLine.value = cellLine.value === value ? '' : value
  document.getElementById('coverage-lookup')?.scrollIntoView({ behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth', block: 'start' })
}
watch(() => [route.query.cell_line, route.query.perturbation], ([context, perturbation]) => {
  cellLine.value = typeof context === 'string' && allContexts.includes(context) ? context : ''
  term.value = typeof perturbation === 'string' ? perturbation : ''
})
function splitName(value: string) {
  return value === 'test' ? '上游 test 候选' : value === 'val' ? '上游 val 候选'
    : value === 'unknown' ? '未核验' : '未声明留出'
}
async function download(missingOnly = false) {
  if (readOnly.value) return
  downloading.value = true; downloadError.value = ''
  downloadController?.abort(); downloadController = new AbortController()
  try {
    const result = await dataCatalogApi.download(missingOnly
      ? { availability: 'missing', model_supported: true }
      : filters(), downloadController.signal)
    downloadBlob(result.blob, missingOnly ? 'model-supported-without-source.csv' : result.filename)
  } catch (reason) { downloadError.value = reason instanceof Error ? reason.message : '目录下载失败' }
  finally { downloading.value = false }
}
</script>

<template>
  <div class="data-catalog-page national-page">
    <MethodsPageHeader eyebrow="DATA ATLAS / PERTURBATION DIRECTORY" :index="readOnly ? undefined : '01'" :title="readOnly ? '案例数据目录' : '数据与扰动'" :description="readOnly ? '查看已发布案例涉及的背景与扰动；此目录是冻结结果的覆盖子集。' : '选择细胞背景与目标基因，核对实测来源及模型支持，找到适合的分析入口。'">
      <RouterLink class="btn btn-primary" :to="readOnly?'/records?view=results':'/research'">{{readOnly?'浏览案例':'新建分析'}} <UiIcon name="arrow" :size="15"/></RouterLink>
    </MethodsPageHeader>
    <div v-if="data && !error" class="catalog-overview"><div class="catalog-overview-label"><span>目录总览</span><small>{{ readOnly ? '已发布案例范围' : '固定源与当前模型 · 不随下方筛选变化' }}</small></div>
      <section v-if="readOnly" class="catalog-metrics" aria-label="白名单案例子集统计"><div><span>已发布案例组合</span><strong>{{data.summary.pairs}}</strong></div><div><span>有固定源实测记录</span><strong>{{data.source_verified?data.summary.measured_pairs:'未知'}}</strong></div><div><span>包含冻结模型结果</span><strong>{{data.summary.model_supported_pairs}}</strong></div><div><span>案例涉及背景</span><strong>{{data.summary.contexts.length}}</strong></div></section>
      <section v-else class="catalog-metrics" aria-label="四背景总体覆盖">
        <div><span>本源有实测的组合</span><strong>{{ data.source_verified ? data.summary.measured_pairs.toLocaleString() : '未知' }}</strong></div>
        <div><span>模型词表支持的组合</span><strong>{{ data.summary.model_supported_pairs.toLocaleString() }}</strong></div>
        <div><span>词表支持 · 本源无记录</span><strong>{{ data.summary.model_supported_unmeasured_pairs?.toLocaleString() ?? '未知' }}</strong></div>
        <div><span>本地已核验的组合</span><strong>{{ data.summary.local_verified_pairs }}</strong></div>
      </section>
    </div>
    <section class="card catalog-table-card" id="coverage-lookup" aria-labelledby="coverage-lookup-title">
      <div class="atlas-section-heading"><h2 id="coverage-lookup-title">查询研究组合 <span>FIND YOUR DATA</span></h2><span>背景 × 扰动 → 分析入口</span></div>
      <p v-if="cellLine || term" class="catalog-query-focus">当前查询：<strong>{{ cellLine || (readOnly ? "全部案例背景" : "全部四背景") }} / {{ term || "全部扰动" }}</strong>。下方按组合显示可用分析入口。</p><form class="catalog-filters" @submit.prevent="load">
        <label>细胞背景<select v-model="cellLine" aria-label="数据目录细胞背景"><option value="">{{readOnly?'全部案例背景':'全部四背景'}}</option><option v-for="context in contexts" :key="context">{{ context }}</option></select></label>
        <label class="catalog-search">搜索扰动基因<input v-model="term" type="search" maxlength="64" placeholder="例如 ALDOA、ABHD11" aria-label="搜索扰动基因" /></label>
        <label>实测状态<select v-model="availability" aria-label="实测状态"><option value="all">全部</option><option value="measured">本源有实测</option><option value="missing">本源无记录</option><option value="unknown">源状态未知</option></select></label>
        <label>{{readOnly?'模型结果':'模型词表'}}<select v-model="support" aria-label="模型词表支持"><option value="all">全部</option><option value="yes">{{readOnly?'已发布':'支持'}}</option><option value="no">{{readOnly?'未发布':'不支持'}}</option></select></label>
        <button class="btn btn-primary catalog-filter-submit" type="submit" :disabled="loading">查询组合 <UiIcon name="arrow" :size="14"/></button>
      </form>
      <div class="catalog-results-bar"><span role="status">{{ loading ? '正在读取…' : error ? '查询暂不可用' : data ? `匹配 ${data.total.toLocaleString()} 个组合` : '尚未读取覆盖数据' }}</span><div v-if="!readOnly"><button class="btn btn-sm" :disabled="downloading || !data || !!error || loading" @click="download()">下载完整筛选 CSV</button><button class="btn btn-sm" :disabled="downloading || !data?.source_verified || !!error || loading" @click="download(true)">下载全部支持但本源无记录组合</button></div></div>
      <p v-if="downloadError" class="notice notice-danger" role="alert">{{ downloadError }}</p>
      <div v-if="!error" class="table-wrap catalog-scroll" :aria-busy="loading"><table class="table catalog-pairs"><thead><tr><th>背景 / 扰动</th><th>本源实测细胞</th><th v-if="!readOnly">本地已核验</th><th>{{readOnly?'冻结模型结果':'模型词表'}}</th><th>上游划分声明</th><th>{{readOnly?'案例入口':'分析入口'}}</th></tr></thead><tbody><tr v-for="row in data?.items ?? []" :key="`${row.cell_line}-${row.perturbation}`"><td><strong class="mono">{{ row.perturbation }}</strong><small>{{ row.cell_line }}</small></td><td><span :class="{'catalog-measured':row.source_status==='measured'}">{{ row.source_status === 'unknown' ? '未知' : row.source_status === 'not_in_source' ? '本源无记录' : row.source_cell_count?.toLocaleString() }}</span></td><td v-if="!readOnly">{{ row.local_verified ? `${row.local_measured_cells.toLocaleString()} 个细胞` : '未下载或未核验' }}</td><td>{{ readOnly ? (row.model_supported ? '已发布' : '未发布') : (row.model_supported ? '支持' : '不支持') }}</td><td>{{ splitName(row.official_split) }}</td><td class="catalog-actions"><RouterLink v-if="readOnly" class="btn btn-sm" :to="{path:'/records',query:{q:row.perturbation}}">浏览相关案例</RouterLink><template v-else><RouterLink v-if="row.recommended_action==='measured'" class="btn btn-sm btn-primary" :to="destination(row, '/measured')">直接分析实测</RouterLink><RouterLink v-if="row.model_supported && row.source_status!=='unknown'" class="btn btn-sm" :to="destination(row, '/workbench')">{{ row.source_status === 'measured' ? '预测并评估' : '探索预测' }}</RouterLink><span v-if="row.recommended_action==='check_source'" class="muted">先核验来源</span><span v-else-if="row.recommended_action==='unsupported'" class="muted">当前模型不支持</span></template></td></tr></tbody></table></div>
      <p v-if="loading && !data" class="catalog-empty" role="status">正在读取公开数据覆盖…</p>
      <p v-if="error" class="catalog-empty">请重新读取目录后继续查询。</p>
      <p v-if="!loading && !error && data && !data.items.length" class="catalog-empty">没有匹配的组合，请调整搜索或筛选条件。</p>
      <TablePager v-if="!error && data" v-model:page="page" v-model:page-size="pageSize" :pages="pages" :total="data?.total ?? 0" />
    </section>
    <section class="catalog-boundary">
      <div><strong>{{readOnly?'公开案例白名单 · 冻结结果子集':'固定公开源 · State-Replogle-Filtered'}}</strong><p>{{readOnly?'统计范围仅包含已发布案例的背景与扰动组合；未列出的组合不能按缺失实测或模型不支持解释。':'“本源无记录”仅指当前固定 filtered 版本，不代表其他研究中没有实测。源中的细胞数与本地已核验下载数分别列出。'}}</p></div>
      <a v-if="data" :href="data.source.url" target="_blank" rel="noopener">查看公开来源 ↗</a>
    </section>
    <div v-if="error" class="notice notice-danger" role="alert">{{ error }} <button class="btn btn-sm" @click="load">重试</button></div>
    <template v-if="data && !error">
      <p v-if="!data.source_verified" class="notice notice-warning" role="status">源索引缺失或核验未通过：覆盖状态为未知，请先检查源目录，不能按零细胞判断。</p>
      <div class="atlas-section-heading"><h2>细胞背景与覆盖 <span>CELL CONTEXTS</span></h2><span>选择背景返回查询结果</span></div>
      <section class="atlas-context-grid" aria-label="按细胞背景筛选"><button v-for="(context, index) in data.summary.contexts" :key="context.cell_line" class="atlas-context-card" :class="{ active: cellLine === context.cell_line }" :aria-pressed="cellLine === context.cell_line" @click="chooseContext(context.cell_line)"><div class="atlas-context-card-head"><svg viewBox="0 0 80 72" aria-hidden="true"><path :d="index % 2 === 0 ? 'M12 27C20 7 58 8 69 28S57 64 35 64S3 48 12 27Z' : 'M17 15C33 3 59 15 66 33S57 64 35 63S2 29 17 15Z'" fill="currentColor" fill-opacity=".14" stroke="currentColor" stroke-opacity=".6"/><ellipse cx="39" cy="35" rx="14" ry="14" fill="currentColor" fill-opacity=".4"/><circle cx="36" cy="32" r="5" fill="currentColor" fill-opacity=".6"/><path d="m20 42 6 6m28-22 4 7m-8 18 6-2" stroke="currentColor" stroke-width="3" stroke-linecap="round" opacity=".55"/></svg><div><strong>{{ context.cell_line }}</strong><span>{{ cellLine === context.cell_line ? '当前筛选' : '公开扰动背景' }}</span></div><UiIcon :name="cellLine === context.cell_line ? 'check' : 'arrow'" :size="15"/></div><dl><div><dt>{{readOnly?'源总数不在展示范围':'本源细胞 · 含对照'}}</dt><dd>{{ context.source_total_cells?.toLocaleString() ?? '未知' }}</dd></div><div><dt>有实测扰动</dt><dd>{{ data.source_verified ? context.measured_pairs.toLocaleString() : '未知' }}</dd></div></dl><footer><span>{{readOnly?'含模型结果的组合':'模型词表支持'}} {{ context.model_supported_pairs.toLocaleString() }}</span><span>筛选组合 ↗</span></footer></button></section>
      <details class="catalog-contexts"><summary>{{readOnly?'查看案例子集统计与上游版本':'查看各背景的完整覆盖统计与上游版本'}}</summary><div class="table-wrap"><table class="table"><thead><tr><th>背景</th><th>本源细胞总数（含对照）</th><th>有实测的扰动</th><th>{{readOnly?'含模型结果':'词表支持'}}</th><th>支持且本源无记录</th></tr></thead><tbody><tr v-for="context in data.summary.contexts" :key="context.cell_line"><td>{{ context.cell_line }}</td><td>{{ context.source_total_cells?.toLocaleString() ?? '未知' }}</td><td>{{ data.source_verified ? context.measured_pairs : '未知' }}</td><td>{{ context.model_supported_pairs }}</td><td>{{ context.model_supported_unmeasured_pairs ?? '未知' }}</td></tr></tbody></table></div><dl class="atlas-version"><div><dt>来源仓库</dt><dd>{{ data.source.repo }}</dd></div><div><dt>固定版本</dt><dd class="mono">{{ data.source.revision }}</dd></div><div><dt>目录范围</dt><dd>{{ data.source.scope }}</dd></div></dl></details>
    </template>
    <nav v-if="!readOnly" class="atlas-next" aria-label="继续了解数据图谱"><span>继续了解</span><RouterLink to="/methods/backgrounds"><strong>细胞与样本</strong><small>对照来源与表达面板</small><span aria-hidden="true">↗</span></RouterLink><RouterLink to="/methods/models"><strong>模型与方法</strong><small>从表达预测到功能推断</small><span aria-hidden="true">↗</span></RouterLink><RouterLink to="/methods/coverage"><strong>代谢覆盖</strong><small>代谢基因与任务范围</small><span aria-hidden="true">↗</span></RouterLink></nav>
    <aside class="catalog-notes"><p>模型词表支持只表示可编码该目标，不代表泛化效果已验证。上游 test / val 是公开配置声明的候选，本项目尚未独立核实 checkpoint 训练排除与泛化结果。</p><p>{{readOnly?'公开案例目录不提供完整源细胞总数、私有下载状态或全库 CSV。单个案例中的细胞数与来源以其冻结记录为准。':'旧 K562 本地评估列表仅含选取的部分目标；本目录采用四背景固定上游配置与全量 obs 计数。对照细胞用于来源总数核对，不作为扰动目标显示。'}}</p></aside>
  </div>
</template>

